/**
 * Identification du logiciel qui a produit un G-code (« Généré le plus probablement par »).
 *
 * 1. Signature explicite en commentaire d'en-tête, quand le slicer en laisse une :
 *    `; generated by PrusaSlicer 2.7.1 on …` (Prusa, SuperSlicer, Orca, Anycubic Slicer Next,
 *    Creality Print, Simplify3D…), `;Generated with Cura_SteamEngine 5.4.0`, `; <IceSL …>`,
 *    `; BambuStudio 01.09.00.70`, `;Sliced by ideaMaker 4.4`…
 * 2. À défaut, déduction d'après le style des marqueurs de type de ligne, propre à chaque famille
 *    (`;TYPE:Inner wall` Orca/Bambu, `;TYPE:External perimeter` Prusa, `;TYPE:WALL-OUTER` Cura,
 *    `; feature outer perimeter` Simplify3D, `; <layer>` IceSL).
 */

export interface GCodeGenerator {
  name: string;
  /** Vrai quand le nom est déduit du format plutôt que lu dans une signature explicite. */
  inferred: boolean;
}

// Noms tels qu'écrits dans les fichiers → nom commercial.
const DISPLAY_NAMES: [RegExp, string][] = [
  [/^AnycubicSlicerNext\b/i, 'Anycubic Slicer Next'],
  [/^Creality[ _]?Print\b/i, 'Creality Print'],
  [/^BambuStudio\b/i, 'Bambu Studio'],
  [/^Orca[ _]?Slicer\b/i, 'OrcaSlicer'],
  [/^Cura_SteamEngine\b/i, 'UltiMaker Cura'],
  [/^Simplify3D(\(R\))?/i, 'Simplify3D'],
  [/^ElegooSlicer\b/i, 'Elegoo Slicer'],
  [/^SuperSlicer\b/i, 'SuperSlicer'],
  [/^PrusaSlicer\b/i, 'PrusaSlicer'],
];

/** « Creality_Print V7.1.0.4414 » → « Creality Print 7.1.0.4414 ». */
function displayName(raw: string) {
  let name = raw.trim();
  for (const [re, pretty] of DISPLAY_NAMES) {
    if (re.test(name)) { name = name.replace(re, pretty); break; }
  }
  return name
    .replace(/_/g, ' ')
    .replace(/\s+Version\s+/i, ' ')
    .replace(/\s+v(?=\d)/i, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const MONTHS: Record<string, string> = {
  jan: 'janvier', feb: 'février', mar: 'mars', apr: 'avril', may: 'mai', jun: 'juin',
  jul: 'juillet', aug: 'août', sep: 'septembre', oct: 'octobre', nov: 'novembre', dec: 'décembre',
};

/** Date de compilation au format `__DATE__` (« Jul  9 2025 ») → « 9 juillet 2025 ». */
const frenchDate = (month: string, day: string, year: string) =>
  `${parseInt(day, 10)} ${MONTHS[month.toLowerCase()] ?? month} ${year}`;

const SIGNATURES:[RegExp, (m: RegExpExecArray) => string][] = [
  [/generated with\s+(cura_steamengine|cura)\s*([\d.]*)/i, (m) => `UltiMaker Cura ${m[2]}`],
  [/generated by\s+(.+?)(?:\s+on\s+\d{4}-\d{2}-\d{2}.*)?$/i, (m) => displayName(m[1])],
  [/^\s*<IceSL\s+([A-Za-z]{3})\s+(\d{1,2})\s+(\d{4})/i, (m) => `IceSL (version du ${frenchDate(m[1], m[2], m[3])})`],
  [/^\s*(BambuStudio|OrcaSlicer|ElegooSlicer)\s+v?([\d.]+)\s*$/i, (m) => displayName(`${m[1]} ${m[2]}`)],
  [/sliced by\s+(ideamaker[\s\d.]*)/i, (m) => m[1].replace(/ideamaker/i, 'ideaMaker')],
  [/KISSlicer/i, () => 'KISSlicer'],
  [/Kiri:Moto/i, () => 'Kiri:Moto'],
  [/MatterSlice/i, () => 'MatterControl'],
  [/FlashPrint/i, () => 'FlashPrint'],
];

/** Signature explicite contenue dans un commentaire (sans le `;`), ou null. */
export function detectGeneratorSignature(comment: string): string | null {
  for (const [re, format] of SIGNATURES) {
    const m = re.exec(comment);
    if (m) return format(m).trim();
  }
  return null;
}

const normalize = (name: string) => name.toLowerCase().replace(/[^a-z]/g, '');

const ORCA_FEATURES = new Set([
  'innerwall', 'outerwall', 'overhangwall', 'sparseinfill', 'internalsolidinfill',
  'topsurface', 'bottomsurface', 'internalbridge', 'gapinfill',
]);
const PRUSA_FEATURES = new Set([
  'perimeter', 'externalperimeter', 'overhangperimeter', 'internalinfill', 'solidinfill',
  'topsolidinfill', 'bridgeinfill', 'gapfill', 'skirtbrim', 'supportmaterial', 'wipetower',
]);

/**
 * Famille de slicer d'après le nom brut d'un marqueur de type (`;TYPE:<nom>`), ou null s'il ne
 * permet pas de trancher (« Custom », « Bridge »… communs à plusieurs familles).
 */
export function guessGeneratorFromFeature(rawName: string, simplify3DStyle: boolean): string | null {
  if (simplify3DStyle) return 'Simplify3D';
  const raw = rawName.trim();
  if (/^[A-Z]+(-[A-Z]+)*$/.test(raw)) return 'UltiMaker Cura ou dérivé';
  const key = normalize(raw);
  if (ORCA_FEATURES.has(key)) return 'OrcaSlicer / Bambu Studio ou dérivé';
  if (PRUSA_FEATURES.has(key)) return 'PrusaSlicer ou dérivé';
  return null;
}
